    const agentRiskSums     = new Map<string, number>(); // T523: per-agent risk sum for avgRisk ranking
    const agentBlockCounts  = new Map<string, number>(); // T465: per-agent block counts for this tool
    const methodCounts      = new Map<string, number>(); // T410
    const methodRiskSums    = new Map<string, number>(); // T573: per-method risk sum for avgRisk ranking
    const methodBlockCounts = new Map<string, number>(); // T642: per-method block counts for this tool
    const sessionIds        = new Set<string>(); // T376
    const sessionCounts     = new Map<string, number>(); // T420: per-session op count
    const sessionRiskSums   = new Map<string, number>(); // T529: per-session risk sum for avgRisk ranking
