    // T523: topAgentsByRisk — top 5 agents by avgRisk when using this tool
    const topAgentsByRisk = [...agentRiskSums.entries()]
      .map(([agentId, riskSum]) => ({ agentId, avgRisk: riskSum / (agentCounts.get(agentId) ?? 1) }))
      .sort((a, b) => b.avgRisk - a.avgRisk)
