    // T465: topBlockedAgents — agents most often blocked using this tool
    const topBlockedAgents = [...agentBlockCounts.entries()].sort((a, b) => b[1] - a[1]).slice(0, 5)
      .map(([agentId, blocked]) => ({ agentId, blocked }));
    // T420: topSessions — top 5 sessions where this tool is most used
    const topSessions = [...sessionCounts.entries()].sort((a, b) => b[1] - a[1]).slice(0, 5)
      .map(([sessionId, count]) => ({ sessionId, count }));
    // T428: topMethods — top 5 methods used with this tool
    const topMethods = [...methodCounts.entries()].sort((a, b) => b[1] - a[1]).slice(0, 5)
      .map(([method, count]) => ({ method, count }));
    // T410: byMethod — counts per method for this tool
    const byMethod: Record<string, number> = {};
    for (const [method, count] of methodCounts) byMethod[method] = count;
    // T573: topRiskMethods — top 5 methods by avgRisk for this tool
    const topRiskMethods = [...methodRiskSums.entries()]
      .map(([method, riskSum]) => ({ method, avgRisk: riskSum / (methodCounts.get(method) ?? 1) }))
