    const toolRiskBuckets: Record<string, number> = { '0.0-0.2': 0, '0.2-0.4': 0, '0.4-0.6': 0, '0.6-0.8': 0, '0.8-1.0': 0 };
    for (const log of logs) {
      const r = log.decision.riskScore;
      const bkt = r < 0.2 ? '0.0-0.2' : r < 0.4 ? '0.2-0.4' : r < 0.6 ? '0.4-0.6' : r < 0.8 ? '0.6-0.8' : '0.8-1.0';
      toolRiskBuckets[bkt]!++;
    }
    // T453: medianRiskScore for this tool
    const toolSortedRisks = logs.map(l => l.decision.riskScore).sort((a, b) => a - b);
    const toolMid = Math.floor(toolSortedRisks.length / 2);
    const toolMedianRisk = toolSortedRisks.length % 2 === 0
      ? (toolSortedRisks[toolMid - 1]! + toolSortedRisks[toolMid]!) / 2
      : toolSortedRisks[toolMid]!;
    // T485/T488: p50/p75/p95 percentile risk scores for this tool
    const toolP25Risk = toolSortedRisks.length > 0 ? toolSortedRisks[Math.floor(toolSortedRisks.length * 0.25)]! : 0; // T600
    const toolP50Risk = toolSortedRisks.length > 0 ? toolSortedRisks[Math.floor(toolSortedRisks.length * 0.50)]! : 0;
    const toolP75Risk = toolSortedRisks.length > 0 ? toolSortedRisks[Math.floor(toolSortedRisks.length * 0.75)]! : 0; // T488
    const toolP95Risk = toolSortedRisks.length > 0 ? toolSortedRisks[Math.floor(toolSortedRisks.length * 0.95)]! : 0;
    // T589: riskScoreStdDev — standard deviation of risk scores for this tool
    const toolMeanRisk = logs.length > 0 ? riskSum / logs.length : 0;
