    // T618: riskVelocity — change in avgRisk from prior 1h to last 1h
    const toolAvgRiskPrior1h = toolPrior1hLogs.length > 0 ? toolPrior1hLogs.reduce((s, l) => s + l.decision.riskScore, 0) / toolPrior1hLogs.length : null;
    const riskVelocity = avgRiskLast1h !== null && toolAvgRiskPrior1h !== null ? avgRiskLast1h - toolAvgRiskPrior1h : null;
    // T619: blockVelocity — change in block count from prior 1h to last 1h
    const toolBlocksLast1h  = toolLast1hLogs.filter(l => l.decision.action === 'block').length;
