      const hourLogs  = logs.filter(l => { const t = l.operation.timestamp.getTime(); return t >= hourStart && t < hourEnd; });
      return hourLogs.length > 0 ? hourLogs.reduce((s, l) => s + l.decision.riskScore, 0) / hourLogs.length : null;
